use vstd::prelude::*;
use vstd::collections::vec::Vec;

verus! {
    // Given an input vector `arr` of i32 and a value `elem`,
    // produce a new vector that interleaves `elem` before each element of `arr`.
    //
    // Post‐conditions:
    //   1. The resulting vector has length = 2 * arr.len().
    //   2. For every k < arr.len():
    //        result[2*k]   == elem
    //        result[2*k+1] == arr[k]
    fn insert_before_each(arr: &Vec<i32>, elem: i32) -> (result: Vec<i32>)
        ensures
            result.len() == arr.len() * 2,
            forall |k: usize| k < arr.len() ==>
                result[2*k] == elem &&
                result[2*k + 1] == arr[k],
    {
        let n = arr.len();
        let mut res: Vec<i32> = Vec::new();
        let mut i: usize = 0;
        while i < n
            invariant
                // We never walk past the end.
                i <= n,
                // So far, we have built exactly 2*i elements.
                res.len() == 2 * i,
                // And those 2*i elements satisfy the interleaving property
                // up to index i:
                forall |j: usize| j < i ==>
                    res[2*j] == elem &&
                    res[2*j + 1] == arr[j],
            decreases n - i,
        {
            // Push the interleaving element
            res.push(elem);
            // Push the original element arr[i]
            // `index` is a safe way to read arr[i].
            res.push(arr.index(i));
            i = i + 1;
        }
        res
    }
}

fn main() {
    // Example usage (not verified):
    let v = Vec::from_slice(&[10, 20, 30]);
    let out = insert_before_each(&v, 5);
    // out should be [5,10, 5,20, 5,30]
    println!("{:?}", out.as_slice());
}